// Запрос в API Канала: { url, token_env, body }. Токен узел отправки берёт из $env[token_env],
// в данные выполнения он не попадает. Новый Канал = новая функция в CHANNELS.
const GRAPH = $env.META_GRAPH_BASE_URL;
// Вне окна 24 часов WhatsApp принимает только шаблон «есть новости»: одобрен у Meta на pl и en
// (docs/whatsapp-setup.md). Клиент отвечает на него — окно открывается снова.
const WHATSAPP_NEWS_TEMPLATE = 'news_update';

// Messenger и Instagram Direct — один Send API Messenger Platform, токен страницы: Instagram —
// страницы, связанной с аккаунтом Instagram. Вне окна 24 часов оба пускают только ответ человека
// с меткой HUMAN_AGENT (до 7 дней). Ответ Ассистента всегда в окне: он идёт сразу за сообщением Клиента.
function sendApi(token_env) {
  return (m) => ({
    url: `${GRAPH}/me/messages`,
    token_env,
    body: {
      recipient: { id: m.sender_id },
      ...(m.in_window ? { messaging_type: 'RESPONSE' } : { messaging_type: 'MESSAGE_TAG', tag: 'HUMAN_AGENT' }),
      message: { text: m.text },
    },
  });
}

function whatsapp(m) {
  const message = m.in_window
    ? { type: 'text', text: { body: m.text } }
    : { type: 'template', template: { name: WHATSAPP_NEWS_TEMPLATE, language: { code: m.language === 'pl' ? 'pl' : 'en' } } };
  return {
    url: `${GRAPH}/${m.account_id}/messages`,
    token_env: 'WHATSAPP_ACCESS_TOKEN',
    body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: m.sender_id, ...message },
  };
}

const CHANNELS = {
  messenger: sendApi('META_PAGE_ACCESS_TOKEN'),
  instagram: sendApi('INSTAGRAM_ACCESS_TOKEN'),
  whatsapp,
};
const build = CHANNELS[$json.channel];
if (!build) throw new Error(`Канал ${$json.channel}: отправка не поддерживается`);
return { json: build($json) };
